<?php $this->assign('title', $row ? 'Editar usuário' : 'Cadastrar usuário'); ?>
<h1><?= h($this->fetch('title')) ?></h1><section class="panel form-panel mt-4"><?= $this->Form->create(null) ?>
<?php foreach (['nome' => 'Nome completo', 'login' => 'Login'] as $field => $label): ?><div class="mb-3"><?= $this->Form->control($field, ['label' => $label, 'value' => $this->request->getData($field) ?? $row?->get($field), 'class' => 'form-control', 'required' => true]) ?></div><?php endforeach; ?>
<div class="mb-3"><?= $this->Form->control('senha', ['label' => $row ? 'Nova senha (deixe em branco para manter)' : 'Senha (mínimo de 6 caracteres)', 'type' => 'password', 'value' => '', 'class' => 'form-control', 'autocomplete' => 'new-password', 'required' => !$row]) ?></div>
<div class="mb-3"><?= $this->Form->control('perfil', ['label' => 'Perfil', 'options' => array_combine(\App\Service\Access::ROLES, \App\Service\Access::ROLES), 'value' => $this->request->getData('perfil') ?? $row?->perfil, 'class' => 'form-select']) ?></div>
<div class="mb-3"><?= $this->Form->control('setores', ['label' => 'Setores autorizados (obrigatório para responsável que não seja computador operacional)', 'multiple' => 'checkbox', 'options' => $sectors, 'value' => $this->request->getData('setores') ?? $selected]) ?></div>
<div class="mb-3"><?= $this->Form->control('computador_operacional',['type'=>'checkbox','label'=>'Computador operacional — lançamentos em todos os setores e consulta dos próprios registros (usar RESPONSAVEL_SETOR)','checked'=>$this->request->is('post')?(bool)$this->request->getData('computador_operacional'):(bool)$row?->computador_operacional]) ?><small>Contas operacionais não precisam de vínculo com setor e não recebem permissões administrativas. Os vínculos dos demais responsáveis continuam válidos.</small></div>
<div class="mb-4"><?= $this->Form->control('ativo', ['label' => 'Usuário ativo', 'type' => 'checkbox', 'checked' => $this->request->is('post') ? (bool)$this->request->getData('ativo') : ($row?->ativo ?? true), 'class' => 'form-check-input']) ?></div>
<?= $this->Form->button('Salvar usuário', ['class' => 'btn btn-primary']) ?><?= $this->Form->end() ?></section>
